pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;

    function setUp() public { c = new AirDropContract(); }

    function testFuzz_property(address actor, address toAddr, uint256 val) public {
        vm.assume(actor != address(0));
        vm.assume(toAddr != address(0));

        Recorder rec = new Recorder();

        address[] memory tos = new address[](1);
        tos[0] = toAddr;
        uint[] memory vs = new uint[](1);
        uint256 amount = bound(val, 1, type(uint256).max);
        vs[0] = amount;

        vm.deal(actor, 1 ether);
        vm.prank(actor);

        bool ok;
        try c.transfer(address(rec), tos, vs) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(rec.lastFrom() == actor);
    }
}

contract Recorder {
    address public lastFrom;
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        lastFrom = from;
        return true;
    }
}
